from ocean.drone import *

# File: clean_lane.py
# -------------------
# Swim to the end of the lane and pick up every bottle on the way.


def clean_square():
    if bottle_present():
        pick_bottle()


def main():
    while front_is_clear():
        clean_square()
        move()
    clean_square()


if __name__ == '__main__':
    main()
